  "codebook": {
    "definition": "Credit-claiming refers to a politician's attempt to generate the belief among constituents or relevant political actors that they are personally responsible for causing the government, or some desirable entity, to execute a positive action or deliver a beneficial outcome.",
    "clarification": "To classify a press release as 'credit-claiming' (1), the text must contain an explicit assertion of personal or collaborative responsibility by the senator for a specific government action, project, funding decision, or legislative success. Key indicators include: 1) Announcing federal grants, appropriations, or projects directed to the senator's home state and highlighting their hand in securing them. 2) Pointing to a specific amendment, bill, or legislative provision that the senator successfully authored, co-sponsored, or navigated through a key legislative hurdle (such as committee approval or chamber passage). 3) Describing personal casework or direct intervention with a federal agency that achieved a positive outcome for a constituent or community group.",
    "positive_examples": [
      {
        "document_id": "1862",
        "explanation": "Senators Baucus and Tester explicitly claim that they 'have delivered on their promise to secure federal funding' of $12.5 million for military projects in Butte, Montana, highlighting their active work on the Appropriations Committee."
      },
      {
        "document_id": "3201",
        "explanation": "Senator Jim Talent claims credit for working directly with USDA officials to expedite the approval of Missouri's drought disaster designation, representing credit-claiming for an administrative action."
      },
      {
        "document_id": "2627",
        "explanation": "Senator Jim Talent announces the Senate's approval of his specific request for $1.5 million in federal funding for a university research facility, illustrating standard credit-claiming for local projects."
      }
    ],
    "negative_clarification": "Do NOT classify a text as credit-claiming (0) if the senator merely expresses an opinion, outlines their stance on an issue, introduces a bill that has not yet passed, or criticizes/praises others without taking personal credit for a finalized positive outcome. Additionally, purely ceremonial statements, eulogies, or general constituent service announcements (such as upcoming town halls or essay contests) should be classified as 0.",
    "negative_examples": [
      {
        "document_id": "656",
        "explanation": "Senator Kerry strongly criticizes the Bush Administration's handling of the Dubai ports deal. While this is highly opinionated, it is pure position-taking and criticism, with no claim of personal responsibility for a positive government outcome."
